
let D,tab='overview';const $=id=>document.getElementById(id),pct=(v,n=1)=>(v*100).toFixed(n)+'%',num=v=>Number(v).toLocaleString('en-US'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function gb(m,x){let z=m.base;for(const t of m.trees){let j=0;while(t.left[j]!==-1)j=Math.fround(x[t.feature[j]])<=t.threshold[j]?t.left[j]:t.right[j];z+=m.rate*t.value[j]}return 1/(1+Math.exp(-z))}
function stat(label,value,sub){return `<div class="stat"><label>${label}</label><strong>${value}</strong><small>${sub}</small></div>`}
function lineChart(lines,{ymin=0,ymax=1,xlabel='Population selected',ylabel='Rate',percent=true}={}){let w=640,h=280,l=58,r=20,b=42,top=22;let x=v=>l+v*(w-l-r),y=v=>h-b-(v-ymin)/(ymax-ymin)*(h-b-top);let s=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(ylabel)} by ${esc(xlabel)}">`;for(let i=0;i<=4;i++){let v=ymin+(ymax-ymin)*i/4;s+=`<line x1="${l}" x2="${w-r}" y1="${y(v)}" y2="${y(v)}" stroke="#e3e9e9"/><text x="${l-10}" y="${y(v)+4}" text-anchor="end" fill="#63787c" font-size="11">${percent?pct(v,1):v.toFixed(1)}</text>`}for(let i=0;i<=4;i++)s+=`<text x="${x(i/4)}" y="${h-22}" text-anchor="middle" fill="#63787c" font-size="11">${pct(i/4,0)}</text>`;for(const a of lines)s+=`<path d="${a.points.map(([u,v],i)=>(i?'L':'M')+x(u)+','+y(v)).join(' ')}" fill="none" stroke="${a.color}" stroke-width="3" ${a.dashed?'stroke-dasharray="5 5"':''}/>`;return s+`<text x="${w/2}" y="${h-2}" text-anchor="middle" fill="#63787c" font-size="11">${xlabel}</text></svg><div class="legend">${lines.map(a=>`<span><i class="dot" style="background:${a.color}"></i>${a.name}</span>`).join('')}</div>`}
function table(head,rows){return `<div class="scroll"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function download(name,text,type='text/csv'){let u=URL.createObjectURL(new Blob([text],{type}));let a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csv(text){const rows=[];let row=[],v='',q=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(q&&text[i+1]==='"'){v+='"';i++}else q=!q}else if(c===','&&!q){row.push(v);v=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&text[i+1]==='\n')i++;row.push(v);if(row.some(x=>x.trim()))rows.push(row);row=[];v=''}else v+=c}row.push(v);if(row.some(x=>x.trim()))rows.push(row);if(q)throw Error('Unclosed CSV quote.');if(rows.length<2)throw Error('Include a header and at least one data row.');let h=rows.shift().map(s=>s.replace(/^\uFEFF/,'').trim());return rows.map((r,i)=>{if(r.length!==h.length)throw Error('Column count mismatch on row '+(i+2));return Object.fromEntries(h.map((k,j)=>[k,r[j]]))})}
async function batch(file){if(!file)return;try{if(file.size>5e6)throw Error('Please use a CSV smaller than 5 MB.');let rows=csv(await file.text());if(rows.length>10000)throw Error('Please use at most 10,000 rows.');let results=rows.map((r,i)=>{try{return scoreRow(r)}catch(e){throw Error('Row '+(i+2)+': '+e.message)}});download('scored-customers.csv',(typeof batchHeader==='undefined'?'':batchHeader+'\n')+results.join('\n'));$('batchStatus').textContent=`Scored ${rows.length} rows. Download ready.`}catch(e){$('batchStatus').textContent=e.message}}
function batchPanel(){return `<div class="panel"><h2>Batch scoring</h2><p class="muted">Use the sample schema. Scoring happens in your browser; uploads are not sent to a server.</p><div class="actions"><a class="btn secondary" href="sample.csv" download>Download sample CSV</a><label class="btn" for="upload">Choose CSV</label><input id="upload" type="file" accept=".csv" style="display:none" onchange="batch(this.files[0])"></div><p id="batchStatus" role="status" class="muted tiny">Maximum 10,000 rows · 5 MB</p></div>`}
function switchTab(v){tab=v;document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===v);b.setAttribute('aria-selected',b.dataset.tab===v)});render()}
fetch('data.json').then(r=>{if(!r.ok)throw Error('Could not load model');return r.json()}).then(d=>{D=d;render()}).catch(e=>{$('content').innerHTML=`<div class="panel error">${esc(e.message)}. Please reload.</div>`});

function vector(r){let x={};for(let k of ['recency','history','mens','womens','newbie']){if(r[k]===undefined||r[k]===''||!Number.isFinite(+r[k]))throw Error('Missing or invalid '+k);x[k]=+r[k]}if(x.recency<1||x.recency>12||x.history<0)throw Error('Recency must be 1–12 and history nonnegative');for(let k of ['mens','womens','newbie'])if(![0,1].includes(x[k]))throw Error(k+' must be 0 or 1');for(let [k,vs] of Object.entries({zip_code:['Rural','Surburban','Urban'],channel:['Multichannel','Phone','Web']})){if(!vs.includes(r[k]))throw Error('Invalid '+k);for(let v of vs)x[k+'_'+v]=+(r[k]===v)}return D.features.map(k=>x[k])}
function scoreRow(r){let x=vector(r),p0=gb(D.models[0],x),p1=gb(D.models[1],x);return [p0.toFixed(6),p1.toFixed(6),(p1-p0).toFixed(6)].join(',')}
function render(){if(tab==='overview')overview();if(tab==='explore')explore();if(tab==='evaluate')evaluate();if(tab==='method')method()}
function gainChart(){let lines=Object.entries(D.curves).map(([name,pts],i)=>({name,color:i?'#d8903e':'#6554bd',points:pts.map(p=>[p.fraction,p.gain])}));lines.push({name:'Random expectation',color:'#9faab5',points:[[0,0],[1,D.curves.Uplift.at(-1).gain]],dashed:true});let ys=lines.flatMap(l=>l.points.map(p=>p[1]));return lineChart(lines,{ymin:Math.min(0,...ys)-.0005,ymax:Math.max(.001,...ys)*1.15,xlabel:'Population targeted',ylabel:'Estimated incremental conversions per population'})}
function overview(){$('content').innerHTML=`<section class="hero"><div><div class="eyebrow">Growth science · causal inference</div><h1>Who buys because<br>you reached out?</h1><p class="muted">Separate purchase propensity from campaign impact. Explore a randomized email experiment and target for incremental conversions.</p><div class="actions"><button class="btn" onclick="switchTab('explore')">Explore uplift ↗</button><button class="btn secondary" onclick="switchTab('evaluate')">Read experiment results</button></div></div><div class="hero-side"><span class="badge">RANDOMIZED EMAIL EXPERIMENT</span><p class="muted">Held-out campaign effect</p><strong>${(D.ate[0]*100).toFixed(2)} pp</strong><p class="muted tiny">Men's email vs no email · conversion outcome<br>95% interval: ${(D.ate[1]*100).toFixed(2)} to ${(D.ate[2]*100).toFixed(2)} percentage points</p></div></section><div class="stats">${stat('Original experiment',num(D.n),'Customers across three arms')}${stat('Modeled population',num(D.included),"Men's email + no email")}${stat('Held-out customers',num(D.split.test),'60 / 20 / 20 split')}${stat('Test Qini area',D.qini.Uplift.toFixed(5),'Centered IPW gain area')}</div><div class="grid"><div class="panel"><h2>Incrementality, not just conversion</h2><p class="muted tiny">Cumulative inverse-propensity-weighted gain on the held-out test set.</p>${gainChart()}<div class="note ${D.qini_ci[0]<=0?'warning':''}">95% bootstrap Qini interval: ${D.qini_ci.map(v=>v.toFixed(5)).join(' to ')}. ${D.qini_ci[0]<=0?'This interval includes zero. Evidence that this ranking improves on random targeting is uncertain.':'Positive offline ranking evidence; a prospective test is still needed.'}</div></div><div class="panel"><h2>Campaign-budget simulator</h2><p class="muted">Compare strategies under the same contact budget.</p><div class="row"><label for="budget">Share of customers targeted</label><b id="budgetLabel">20%</b></div><input id="budget" type="range" min="5" max="100" step="5" value="20" oninput="budget()"><div class="fields"><div class="field"><label for="margin">Assumed margin / conversion ($)</label><input id="margin" type="number" min="0" value="20" oninput="budget()"></div><div class="field"><label for="cost">Assumed contact cost ($)</label><input id="cost" type="number" min="0" value="0.05" step="0.01" oninput="budget()"></div></div><div id="budgetResults"></div><p class="muted tiny">Illustrative profit = estimated incremental conversions × assumed margin − contact cost. Not observed revenue or CRED cashback results.</p></div></div>`;budget()}
function budget(){let f=+$('budget').value/100,n=D.rows.length,k=Math.floor(n*f),margin=+$('margin').value,cost=+$('cost').value;$('budgetLabel').textContent=pct(f,0);if(!Number.isFinite(margin)||margin<0||!Number.isFinite(cost)||cost<0){$('budgetResults').textContent='Enter nonnegative costs and margins.';return}let res=[];for(let [name,key] of [['Uplift','uplift'],['Conversion','p1']]){let r=[...D.rows].sort((a,b)=>b[key]-a[key]).slice(0,k),gain=r.reduce((s,a)=>s+2*a.y*(2*a.t-1),0);res.push([name,gain.toFixed(1),'$'+(gain*margin-k*cost).toFixed(0)])}let gain=D.rows.reduce((s,a)=>s+2*a.y*(2*a.t-1),0)*f;res.push(['Random expectation',gain.toFixed(1),'$'+(gain*margin-k*cost).toFixed(0)]);$('budgetResults').innerHTML=`<p class="muted">Targeting <b>${num(k)}</b> held-out profiles</p>${table(['Strategy','Estimated extra conversions','Simulated profit'],res)}`}
let sample=0;
function explore(){let r=D.rows[sample];$('content').innerHTML=`<div class="eyebrow">Customer explorer</div><h1>Two predictions. One difference.</h1><p class="muted">The T-learner estimates conversion with and without an email, then subtracts the two.</p><div class="grid"><div class="panel"><div class="row"><h2>Customer history</h2><button class="btn secondary" onclick="sample=(sample+23)%D.rows.length;explore()">Next sample →</button></div><div class="fields">${['recency','history','mens','womens','newbie'].map(k=>`<div class="field"><label for="f_${k}">${({recency:'Months since purchase (1–12)',history:'Past-year spend ($)',mens:"Bought men’s products (0/1)",womens:"Bought women’s products (0/1)",newbie:'New customer (0/1)'})[k]}</label><input id="f_${k}" type="number" step="any" value="${r.x[k]}"></div>`).join('')}${Object.entries({zip_code:['Rural','Surburban','Urban'],channel:['Multichannel','Phone','Web']}).map(([k,vs])=>`<div class="field"><label for="f_${k}">${k==='zip_code'?'Area type':'Purchase channel'}</label><select id="f_${k}">${vs.map(v=>`<option ${r.x[k]===v?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}</div><div class="actions"><button class="btn" onclick="score()">Estimate uplift</button></div><p class="muted tiny">“Surburban” preserves the original dataset category spelling.</p></div><div class="panel" id="prediction"></div></div>${batchPanel()}<div class="note">Individual treatment effects are unobservable: each customer received only one assignment. These estimates are suitable for evaluating groups and policies, not claims about a specific person's true response.</div>`;score()}
function score(){try{let r=Object.fromEntries(['recency','history','mens','womens','newbie','zip_code','channel'].map(k=>[k,$('f_'+k).value])),x=vector(r),p0=gb(D.models[0],x),p1=gb(D.models[1],x),u=p1-p0;$('prediction').innerHTML=`<span class="badge">ESTIMATED CONVERSION UPLIFT</span><div class="big">${u>=0?'+':''}${(u*100).toFixed(2)} <span style="font-size:24px">pp</span></div>${table(['No email','Men’s email'],[[pct(p0,2),pct(p1,2)]])}<p class="muted">${u>0?'The model estimates a higher conversion probability with this campaign.':'The model does not estimate a positive conversion effect for this profile.'}</p><div class="note">This is a model estimate, not a verified individual treatment effect. The dataset measures email campaigns, not rewards or cashback.</div>`}catch(e){$('prediction').innerHTML=`<p class="error">${esc(e.message)}</p>`}}
function evaluate(){$('content').innerHTML=`<div class="eyebrow">Experiment evidence</div><h1>Separate effect from noise.</h1><div class="panel"><h2>Original randomized arms</h2><p class="muted tiny">Descriptive statistics on all 64,000 customers. Modeling below uses men's email versus no email only.</p>${table(['Assignment','Customers','Conversion rate','Visit rate'],D.arms.map(a=>[a.name,num(a.n),pct(a.conversion,2),pct(a.visit,2)]))}</div><div class="grid"><div class="panel"><h2>Model selection</h2><p class="muted">Two depth settings, chosen using validation Qini. The test set was not used to pick a model.</p>${table(['Tree depth','Validation Qini'],D.runs.map(r=>[r.depth+(r.depth===D.depth?' <span class="pill">selected</span>':''),r.validation_qini.toFixed(6)]))}<h3>Held-out ranking</h3>${table(['Strategy','Test Qini area'],Object.entries(D.qini).map(([k,v])=>[k,v.toFixed(6)]))}<p class="muted tiny">Qini here is the trapezoidal area of the IPW gain curve above its random-targeting diagonal, using 5% population increments. This definition may differ from library defaults.</p></div><div class="panel"><h2>Uncertainty matters</h2><div class="big" style="font-size:38px">${(D.ate[0]*100).toFixed(2)} pp</div><p>Held-out average treatment effect</p><p class="muted">Approximate 95% normal interval: ${(D.ate[1]*100).toFixed(2)} to ${(D.ate[2]*100).toFixed(2)} pp.</p><div class="note">Qini 95% percentile interval from 300 held-out row bootstraps: <b>${D.qini_ci.map(v=>v.toFixed(6)).join(' to ')}</b>. This conditions on trained models and does not include training uncertainty.</div><p class="muted">Rare conversions make fine-grained treatment-effect estimates noisy. A positive overall campaign effect does not automatically mean targeting improves results.</p></div></div><div class="panel"><h2>Next experiment</h2><p>Freeze a targeting policy chosen on validation data. Randomize eligible customers to that policy versus the current strategy, with equal contact budgets. Pre-register incremental conversion as the primary outcome, use intent-to-treat analysis, and track unsubscribe and complaint rates as guardrails.</p></div>`}
function method(){$('content').innerHTML=`<div class="eyebrow">Research notes</div><h1>Prediction is not causation.</h1><div class="grid"><div class="panel"><h2>Reproducible workflow</h2><div class="steps"><div><b>01 / Randomized source</b>Kevin Hillstrom’s 2008 MineThatData email experiment. Three randomized arms; 64,000 customers. <a href="https://blog.minethatdata.com/2008/03/minethatdata-e-mail-analytics-and-data.html" target="_blank" rel="noreferrer">Original source ↗</a></div><div><b>02 / Define the estimand</b>Two-week conversion effect of men's email versus no email. The women's campaign is excluded from modeling. Conditional assignment probability is 0.5.</div><div><b>03 / Pre-treatment features only</b>Recency, historical spend, category purchases, new-customer status, area and channel. Exclude visit, conversion and spend outcomes from features.</div><div><b>04 / T-learner</b>Train separate boosting models in each arm. Estimated uplift = P(conversion | email, X) − P(conversion | control, X). Seed 42; 60/20/20 split stratified by assignment and outcome.</div><div><b>05 / Offline policy evaluation</b>Rank held-out customers. IPW pseudo-outcome = 2 × outcome × (2 × treatment − 1). Cumulative gain estimates incremental conversions if that selected group were contacted.</div></div></div><div><div class="panel"><h2>What this cannot prove</h2><p>The experiment does not identify each individual's effect. It also does not establish effects for Indian fintech customers, cashback, or a different campaign.</p><p>Two independent response models may produce noisy differences. Results assume randomized assignment, no interference, consistent treatment, and valid recorded outcomes.</p><p>Budget exploration is descriptive. Choosing the best-looking test-set budget would bias claims; freeze your policy using validation and verify it prospectively.</p></div><div class="panel"><h2>Take the project with you</h2><p class="muted">Training pipeline, model exports, metrics, SQL, Streamlit app and interview notes.</p><a class="btn" href="project.zip" download>Download full project ↓</a><div class="actions"><a href="metrics.json" download>Metrics JSON</a><a href="INTERVIEW_GUIDE.md" download>Interview guide</a></div></div></div></div>`}

const batchHeader="control_probability,treatment_probability,estimated_uplift";
